def compute(vars):
    total_net_derivatives_without_foreign_exchange = vars["v1"] - vars["v2"]
    return {
        "value": total_net_derivatives_without_foreign_exchange,
        "trace": {
            "total_net_of_cash_collateral": vars["v1"],
            "foreign_exchange": vars["v2"],
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
